"""sample-api: generated by the platform template (python -m platformkit.new_service).

Endpoints every platform service has:
  GET /health   -> {"status": "ok"}  (Kubernetes readiness and liveness probes)
  GET /metrics  -> Prometheus metrics (request count by path and status)
  GET /         -> service info
"""
from __future__ import annotations

import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from prometheus_client import CONTENT_TYPE_LATEST, Counter, generate_latest

SERVICE = "sample-api"
TEAM = "platform"
REQUESTS = Counter("http_requests_total", "HTTP requests", ["path", "status"])


def route(path: str) -> tuple[int, str, bytes]:
    if path == "/health":
        return 200, "application/json", b'{"status": "ok"}'
    if path == "/metrics":
        return 200, CONTENT_TYPE_LATEST, generate_latest()
    if path == "/":
        body = {"service": SERVICE, "team": TEAM, "version": os.environ.get("VERSION", "dev")}
        return 200, "application/json", json.dumps(body).encode()
    return 404, "application/json", b'{"error": "not found"}'


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):  # noqa: N802
        status, ctype, body = route(self.path.split("?")[0])
        REQUESTS.labels(self.path.split("?")[0], str(status)).inc()
        self.send_response(status)
        self.send_header("Content-Type", ctype)
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, *args):  # keep container logs quiet
        pass


def main() -> None:
    port = int(os.environ.get("PORT", "8080"))
    ThreadingHTTPServer(("0.0.0.0", port), Handler).serve_forever()


if __name__ == "__main__":
    main()
